previewCss:
.darma-loader-darma-b14-music-box { --accent: var(--loader-color, #b45309); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .66); position: relative; }
.darma-loader-darma-b14-music-box::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 16%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 22%, var(--accent-2)), color-mix(in srgb, #000 42%, var(--accent-2))); }
.darma-loader-darma-b14-music-box::before { content: ''; position: absolute; z-index: 2; bottom: 16%; left: 6%; width: 36%; height: 34%; background: linear-gradient(90deg, color-mix(in srgb, #000 44%, var(--accent-2)) 0 20%, transparent 20%), repeating-linear-gradient(to bottom, var(--accent-2) 0 18%, transparent 18% 34%); }
.darma-loader-darma-b14-music-box .darma-loader-darma-b14-music-box__cylinder { position: absolute; bottom: 18%; right: 7%; width: 44%; height: 62%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 12%, var(--accent)) 0 60%, transparent 61%), repeating-conic-gradient(from 0deg, color-mix(in srgb, #000 58%, var(--accent)) 0 3.5deg, transparent 3.5deg 22deg); animation: darma-loader-darma-b14-music-box-cyl-spin calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
.darma-loader-darma-b14-music-box .darma-loader-darma-b14-music-box__cylinder::after { content: ''; position: absolute; inset: 40%; border-radius: 50%; background: color-mix(in srgb, #000 45%, var(--accent)); }
.darma-loader-darma-b14-music-box span { position: absolute; bottom: 48%; left: 20%; width: calc(var(--loader-size, 116px) * .1); height: calc(var(--loader-size, 116px) * .085); border-radius: 50%; background: var(--accent-2); animation: darma-loader-darma-b14-music-box-note-float calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b14-music-box span::after { content: ''; position: absolute; left: 82%; bottom: 40%; width: 22%; height: 190%; border-radius: 1px; background: var(--accent-2); }
.darma-loader-darma-b14-music-box span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.1); }
@keyframes darma-loader-darma-b14-music-box-cyl-spin { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b14-music-box-note-float { 0% { opacity: 0; transform: translate(0, 0) rotate(-8deg); } 22% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size, 116px) * -.14), calc(var(--loader-size, 116px) * -.36)) rotate(14deg); } }

